import{_ as o,o as r,c as t,a2 as e}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"출격하고 돌아오는 흐름","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Campaign-Loop.md","filePath":"rules/Campaign-Loop.md"}'),i={name:"rules/Campaign-Loop.md"};function l(s,a,n,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="출격하고-돌아오는-흐름" tabindex="-1">출격하고 돌아오는 흐름 <a class="header-anchor" href="#출격하고-돌아오는-흐름" aria-label="Permalink to &quot;출격하고 돌아오는 흐름&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-campaign-loop.svg?raw=true" alt="출격하고 돌아오는 흐름의 아이소 단계"></p><p>캠페인 한 사이클에서 준비, 원정, 조우, 전투, 결과 반영 단계를 순서대로 진행합니다.</p><h2 id="여섯-단계" tabindex="-1">여섯 단계 <a class="header-anchor" href="#여섯-단계" aria-label="Permalink to &quot;여섯 단계&quot;">​</a></h2><ol><li><strong>거점에서 할 일 고르기:</strong> 정보, 의뢰, 계약과 관계 문제를 살핍니다.</li><li><strong>원정 준비:</strong> 파티, 장비, 식량, 의약품, 경로와 통행권을 준비합니다.</li><li><strong>4방향 원정:</strong> 같은 아이소메트릭 격자에서 지상, 역사와 터널을 이동합니다.</li><li><strong>마주친 일 풀기:</strong> 교섭, 거래, 작업, 은신, 회피 또는 전투를 선택합니다.</li><li><strong>전술 전투:</strong> 결정적 충돌을 같은 격자의 실시간 진형·카드 규칙으로 해결합니다.</li><li><strong>결과 반영:</strong> 부상, 시간, 물자, 관계, 평판, 거점과 노선 상태가 바뀝니다.</li></ol><h2 id="작은-파티에서-큰-세력으로" tabindex="-1">작은 파티에서 큰 세력으로 <a class="header-anchor" href="#작은-파티에서-큰-세력으로" aria-label="Permalink to &quot;작은 파티에서 큰 세력으로&quot;">​</a></h2><p>초기에는 파티 생존과 한 역의 문제를 다룹니다. 신뢰와 직능을 얻으면 작업반이나 상단을 이끌고, 이후에는 여러 역의 협약과 노선 세력의 정책에 개입합니다. 규모가 커져도 플레이어의 선택은 이름 있는 인물과 구체적인 사건을 통해 전달됩니다.</p><h2 id="시간이-흐르는-단위" tabindex="-1">시간이 흐르는 단위 <a class="header-anchor" href="#시간이-흐르는-단위" aria-label="Permalink to &quot;시간이 흐르는 단위&quot;">​</a></h2><ul><li>행동: 한 칸 이동, 대화, 작업, 공격 같은 즉시 결정</li><li>시간: 이동, 피로, 식량, 지역 일정</li><li>하루: 역 생산과 소비, 외부 파티 이동, 노선 안전</li><li>한 주: 외교, 인구 집계, 정통성, 세력 목표</li></ul><p>플레이어 주변은 자세히 계산하고 멀리 있는 세계는 집계 단위로 처리합니다. 세계 전체를 같은 정밀도로 계속 계산하지 않습니다.</p><p>거점의 일일 정산, 주간 긴장도와 세력 규모 확대의 상세 규칙은 <a href="/world/Strongholds-and-Territory.html">거점과 영토</a>, <a href="/world/Economy-and-Production.html">경제와 생산</a>, <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>, <a href="/rules/Campaign-Progression.html">캠페인 진행과 위기</a>에서 이어집니다.</p>',11)])])}const g=o(i,[["render",l]]);export{m as __pageData,g as default};
